/* eslint-disable */
import React, { useMemo, useState } from "react";

/**
 * items: [{ img, title, excerpt, href }]
 * Ordre attendu:
 *   0 = fond, 1 = milieu, 2 = avant
 */
export default function NewsStack({
    items = [],
    className = "",
    // dimensions d'une carte
    cardWidth = 500,
    cardHeight = 500,
    // recouvre 3/5 H et 6/7 W de la carte précédente
    coverHeightRatio = 3 / 5,
    coverWidthRatio = 6 / 7,
}) {
    const [hovered, setHovered] = useState(null);

    // Décalages requis pour "couvrir" les ratios indiqués.
    // Si on couvre 3/5 en hauteur -> on laisse 2/5 visible -> offsetY = 2/5 * H
    // Si on couvre 6/7 en largeur -> on laisse 1/7 visible -> offsetX = 1/7 * W
    const offsetY = useMemo(
        () => (1 - coverHeightRatio) * cardHeight,
        [coverHeightRatio, cardHeight]
    );
    const offsetX = useMemo(
        () => (1 - coverWidthRatio) * cardWidth,
        [coverWidthRatio, cardWidth]
    );

    // Calcule les positions pour 3 couches en cascade droite -> gauche (on utilise "right")
    const layers = useMemo(() => {
        const L = [];
        for (let i = 0; i < 3; i++) {
            L.push({
                top: i * offsetY,
                right: i * offsetX,
                width: cardWidth,
                height: cardHeight,
                rotate: 0, // mets un léger angle si tu veux: i===1 ? 1.2 : i===2 ? -0.8 : 0
                z: 10 + i * 10,
            });
        }
        return L;
    }, [offsetY, offsetX, cardWidth, cardHeight]);

    const containerHeight = useMemo(
        () => layers[layers.length - 1].top + cardHeight + 4,
        [layers, cardHeight]
    );

    const hoverStyle = (i) => {
        const is = hovered === i;
        return {
            transform: `translate3d(${is ? "-6px" : "0"},${is ? "-6px" : "0"},0) rotate(${layers[i].rotate}deg) scale(${is ? 1.03 : 1})`,
            zIndex: is ? 50 : layers[i].z,
            boxShadow: is
                ? "0 22px 56px rgba(0,0,0,.34)"
                : "0 14px 32px rgba(0,0,0,.22)",
            filter: is ? "saturate(1.06) contrast(1.02)" : "saturate(.92)",
            transition:
                "transform .28s cubic-bezier(.2,.8,.2,1), box-shadow .28s ease, filter .28s ease",
        };
    };

    return (
        <div className={`relative ${className}`}>
            <div
                className="relative"
                style={{
                    width: "100%",
                    maxWidth: cardWidth + 2 * offsetX, // marge pour le décalage vers la gauche
                    height: containerHeight,
                }}
            >
                {items.slice(0, 3).map((it, i) => (
                    <article
                        key={i}
                        className="absolute rounded-xl overflow-hidden bg-white cursor-pointer will-change-transform"
                        style={{
                            top: layers[i].top,
                            right: layers[i].right,
                            width: layers[i].width,
                            height: layers[i].height,
                            ...hoverStyle(i),
                        }}
                        onMouseEnter={() => setHovered(i)}
                        onMouseLeave={() => setHovered(null)}
                    >
                        <a href={it.href || "#"} className="block w-full h-full relative" aria-label={it.title}>
                            <img
                                src={it.img}
                                alt={it.title}
                                className="absolute inset-0 w-full h-full object-cover"
                                loading="lazy"
                            />

                            {/* Liseré bleu à droite */}
                            <div className="absolute top-3 right-3 h-[88%] w-1 rounded bg-[#5aa4ff]" />

                            {/* Dégradé + texte : visible en permanence sur la carte avant (i===2), sinon au hover */}
                            <div
                                className={`absolute inset-0 flex items-end p-5 text-white ${hovered === i || i === 2 ? "opacity-100" : "opacity-0"
                                    }`}
                                style={{
                                    background:
                                        "linear-gradient(to top, rgba(0,0,0,.72) 0%, rgba(0,0,0,.05) 60%, rgba(0,0,0,0) 100%)",
                                    transition: "opacity .2s ease",
                                }}
                            >
                                <div className="w-full">
                                    <h4
                                        className="text-lg font-semibold leading-tight"
                                        style={{
                                            display: "-webkit-box",
                                            WebkitLineClamp: 2,
                                            WebkitBoxOrient: "vertical",
                                            overflow: "hidden",
                                        }}
                                    >
                                        {it.title}
                                    </h4>
                                    <p
                                        className="text-sm opacity-95 mt-1"
                                        style={{
                                            display: "-webkit-box",
                                            WebkitLineClamp: 2,
                                            WebkitBoxOrient: "vertical",
                                            overflow: "hidden",
                                        }}
                                    >
                                        {it.excerpt}
                                    </p>
                                </div>
                            </div>
                        </a>
                    </article>
                ))}
            </div>
        </div>
    );
}
